import * as M from './model.js';
import * as N from './staff-network.js';
import {EXTRA_STAFF,staffInfo,staffScene,onDuty} from './staff-catalog.js';
const status={requested:'회신 대기',scheduled:'협의 예정',completed:'협의 완료',cancelled:'취소',missed:'미실시',conflict:'일정 재조정 필요'};
export function createStaffUI(ctx){
 const {getState:get,esc,btn,portrait,personHeading}=ctx;
 function directory(){const s=get();ctx.setModal('함께 일하는 사람들',`<p class="intro">이름을 누르면 인물 기록을 열 수 있습니다. 전문 담당자에게는 학교톡으로 먼저 문의하고 협의 시간을 요청하세요. 근무 시간은 이 가상 학교의 설정입니다.</p><div class="staff-directory">${M.NPCS.map(n=>{const info=staffInfo(n.id);return `<article class="staff-task"><button class="person-card" data-action="profile" data-id="${n.id}">${portrait(n.id,'lg')}<b>${esc(n.id==='teacher'?s.config.teacherName:n.name)}</b><small>${n.role}</small></button>${info?`<p class="staff-availability">${M.clock(n.start)}–${M.clock(n.end)} · ${onDuty(s,n)?'연락 가능':'연락 대기'}</p><p>${n.skills.map(esc).join(' · ')}</p><small>${esc(n.tradeoff)}</small><div class="buttons">${btn('개별 학교톡','staff-chat',`data-id="${n.id}"`)}${btn('협의 일정','staff-consult',`data-id="${n.id}"`)}</div>`:''}</article>`;}).join('')}</div>`,'교직원 명렬표 · 담당과 일정',true);}
 function consult(id,entryId){const s=get(),n=staffInfo(id);if(!n)return;const slots=N.availableSlots(s,id),records=[...N.data(s).consultations.filter(c=>c.personId===id).slice().reverse(),...(s.career?.archives||[]).slice().reverse().flatMap(a=>(a.staffNetwork?.consultations||[]).filter(c=>c.personId===id).map(c=>({...c,archivedYear:a.year})))];
  ctx.setModal(n.name+' · 협의 일정',`${personHeading(id,n.role+' · '+M.ROOMS[n.room].name)}<p>${n.skills.join(' · ')}</p><div class="notice">${esc(n.tradeoff)}<br>요청 → 근무 시간 중 회신 → 개인 스케줄러 기록 → 해당 장소에서 참석 순서입니다. 아직 지나지 않은 약속은 취소 후 다시 요청할 수 있습니다.</div><div class="beta-grid"><label class="beta-field"><span>협의할 주제</span><select id="staff-topic">${n.scenes.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></label><label class="beta-field"><span>수업·약속이 없는 20분</span><select id="staff-slot">${slots.map(x=>`<option value="${x.day}:${x.start}">${M.dateLabel({day:x.day})} ${M.clock(x.start)}–${M.clock(x.start+20)}</option>`).join('')||'<option value="">앞으로 15등교일의 빈 시간이 없습니다.</option>'}</select></label></div><div class="buttons">${btn('학교톡으로 협의 요청','staff-request',`data-id="${id}" ${slots.length?'':'disabled'}`,'primary')}${btn('개별 대화 열기','staff-chat',`data-id="${id}"`)}</div><h4>요청과 협의 기록</h4>${records.map(c=>`<article class="staff-task" ${c.id===entryId?'data-highlight="true"':''}><b>${staffScene(id,c.topic)[1]}</b><p>${M.dateLabel({day:c.day})} ${M.clock(c.start)}–${M.clock(c.end)} · ${c.archivedYear?c.archivedYear+'학년도 보관 · ':''}${c.archivedYear&&['requested','scheduled'].includes(c.status)?'학년도 종료 · 미실시':status[c.status]}</p><small>${M.ROOMS[c.room].name}</small>${c.note?`<p>${esc(c.note)}</p>`:''}${!c.archivedYear&&c.status==='scheduled'?`<label class="beta-field"><span>함께 확인할 내용·다음 확인 사항</span><textarea id="staff-note-${c.id}" maxlength="1000"></textarea></label><div class="buttons">${s.room===c.room?btn('약속 시간에 참석 · 기록','staff-attend',`data-id="${c.id}"`,'primary'):btn('협의 장소로 이동','go-room',`data-id="${c.room}"`)}${btn('일정 취소','staff-cancel',`data-id="${c.id}"`)}</div>`:!c.archivedYear&&c.status==='requested'?btn('요청 취소','staff-cancel',`data-id="${c.id}"`):''}</article>`).join('')||'<p class="empty">아직 협의를 요청하지 않았습니다.</p>'}`,'학교톡 · 개인 일정 연동',true,{key:'staff-'+id,preserveScroll:true});
 }
 function handle(action,el){if(!['staff-chat','staff-consult','staff-request','staff-attend','staff-cancel'].includes(action))return false;const s=get(),id=el.dataset.id;
  if(action==='staff-chat'){ctx.chat(id);return true;}if(action==='staff-consult'){consult(id);return true;}
  let r,personId=id;if(action==='staff-request'){const [day,start]=String(document.getElementById('staff-slot')?.value||'').split(':').map(Number);r=N.request(s,id,document.getElementById('staff-topic')?.value,day,start);}else{personId=N.data(s).consultations.find(c=>c.id===id)?.personId;r=action==='staff-attend'?N.attend(s,id,document.getElementById('staff-note-'+id)?.value):N.cancel(s,id);}
  if(r?.error){ctx.toast(r.error);return true;}if(!r){ctx.toast('현재 단계에서 진행할 수 없습니다.');return true;}ctx.commit();consult(personId,r.id||id);ctx.toast(action==='staff-request'?'협의를 요청했습니다. 게임 시간 2분 이후 담당 근무 시간에 회신이 도착합니다.':action==='staff-attend'?'협의 참석과 후속 확인 사항을 기록했습니다.':'일정 취소를 기록했습니다.');return true;
 }
 return {directory,consult,handle};
}
